(()=>{'use strict';const frame=document.getElementById('game'),stats=document.getElementById('stats'),panel=document.getElementById('tools');const $=id=>document.getElementById(id);const session={version:'V635-090-QA-ONLY',model:'device-local-no-guarantee',start:0,stop:0,device:{ua:navigator.userAgent,screen:[screen.width,screen.height],dpr:devicePixelRatio},samples:[],events:[]};let active=false,watch=null,frameCtx=null;
function attach(){try{const w=frame.contentWindow;if(!w||!w.document||w.document.readyState==='loading')return null;if(frameCtx===w&&w.__v635PhoneProbe)return w.__v635PhoneProbe;frameCtx=w;const q={frames:[],last:0,active:true};function raf(t){if(!q.active)return;if(q.last){q.frames.push(Math.min(2000,t-q.last));if(q.frames.length>300)q.frames.shift();}q.last=t;w.requestAnimationFrame(raf)}w.requestAnimationFrame(raf);w.__v635PhoneProbe=q;return q}catch(err){return null}}
function percentile(a,p){if(!a.length)return null;const b=[...a].sort((x,y)=>x-y);return b[Math.min(b.length-1,Math.floor((b.length-1)*p))]}
function read(){let w,probe,data=null;try{w=frame.contentWindow;probe=attach();data=typeof w.__EVOLVE_V424_PERF__==='function'?w.__EVOLVE_V424_PERF__():null;}catch(e){}let dt=probe?.frames?.filter(x=>x>0)||[];return {wall:Date.now(),elapsed:Math.round((Date.now()-session.start)/1000),fpsRaf:dt.length?+(1000/(dt.reduce((a,b)=>a+b,0)/dt.length)).toFixed(1):null,onePercentLowRaf:dt.length>50?+(1000/percentile(dt,.99)).toFixed(1):null,frameP99ms:dt.length>50?+percentile(dt,.99).toFixed(1):null,normalEnemies:data?.enemies??null,visibleEnemies:data?.visibleEnemies??null,gameFPS:data?.frameEMA?+(1000/data.frameEMA).toFixed(1):null,simMS:data?.simMs??null,drawMS:data?.drawMs??null,gpuMS:data?.gpuMs??null,gpuEnabled:data?.gpu??null,DPR:data?.DPR??null,stageTimer:(w?.document?.getElementById('timerPill')?.textContent||'').trim().slice(0,80),hpLabel:(w?.document?.getElementById('hpPill')?.textContent||'').trim().slice(0,80)} }
function show(s){const state=active?'측정 중':'대기';stats.textContent=`${state} | 화면 FPS ${s.fpsRaf??'-'} · 1% low ${s.onePercentLowRaf??'-'}\n몬스터 ${s.normalEnemies??'-'} (화면 ${s.visibleEnemies??'-'}) | CPU ${s.simMS!=null?s.simMS.toFixed(1):'-'}ms | draw ${s.drawMS!=null?s.drawMS.toFixed(1):'-'}ms | GPU ${s.gpuEnabled?'ON':'OFF'}`;}
$('start').onclick=()=>{if(active)return;session.samples=[];session.events=[];session.start=Date.now();session.stop=0;active=true;$('start').disabled=true;$('stop').disabled=false;$('export').disabled=true;session.events.push({type:'START',at:session.start});};
$('stop').onclick=()=>{if(!active)return;active=false;session.stop=Date.now();session.events.push({type:'STOP',at:session.stop});$('start').disabled=false;$('stop').disabled=true;$('export').disabled=false;};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({...session,warning:'Browser requestAnimationFrame proxy for FPS, NOT thermal measurement or GPU-presented FPS; test only.'},null,2)],{type:'application/json'});const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download='EVOLVE_V635_S23PLUS_QA_'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);};
$('toggle').onclick=()=>{panel.classList.toggle('folded');$('toggle').textContent=panel.classList.contains('folded')?'테스트 기록 표시':'패널 숨김'};
frame.addEventListener('load',()=>{const p=attach();if(active)session.events.push({type:'FRAME_LOAD',at:Date.now(),ok:!!p});});
setInterval(()=>{const s=read();if(active)session.samples.push(s);show(s);},1000);
})();